            "trans": "踏渡江水去采摘水中的荷花芙蓉，长满兰草的沼泽水泽生长着芬芳香草。采摘下这清香的荷花想要赠送给谁呢？我心中日夜思念的人远在遥远漫长的天涯道路上。",
