            "orig": "还顾望旧乡，长路漫浩浩。同心而离居，忧伤以终老。",
            "trans": "回过头来遥遥回望故乡家园，归途漫漫道路辽远浩茫无尽。心心相印的知心人却不得不天各一方离散异地，心中唯有无尽的忧伤伴随一生直到衰老终老。",
