            "orig": "曰：“夫子何哂由也？”曰：“为国以礼，其言不让，是故哂之。”",
            "trans": "曾皙问：“老师刚才为什么笑仲由呢？”孔子说：“治理国家应当讲究谦让礼仪，可是他说话一点都不谦虚礼让，因此我笑他。”",
