            "trans": "曾皙问：“难道公西赤所讲的就不是治理国家的大事吗？”孔子说：“宗庙祭祀和诸侯相会朝见，不是诸侯国家的大事又是什么？公西赤如果只能做个小相赞礼，那么谁还能做辅佐诸侯治国的大相呢？”",
