            "trans": "回想起六国当初创业的先祖先辈，冒着严霜雨露，披荆斩棘开荒辟土，才好不容易开拓下这尺土寸金的一寸疆土。后代懦弱子孙看待祖先家业却一点也不加珍惜，双手奉上拱手送给敌人，如同丢弃路边荒野草芥毫无痛惜。今天割让五座城池，明天割让十座城池，这样割地妥协之后才能换得一个夜晚的片刻苟安好觉。清晨起床放眼张望四境边疆，而贪婪暴虐的秦国虎狼大军又重新兵临城下了！",
