            "trans": "既然这样，那么六国诸侯能够割让的国土是极其有限的，而凶暴强秦的贪婪欲望却永远贪得无厌，六国奉送割让得越频繁厚重，秦国侵略蚕食就越紧迫凶急。所以用不着真正交战交锋，双方谁强谁弱、谁胜谁负在暗中早就已经一目了然判定了。最终落得家破国亡彻底颠覆的下场，按客观常理本来就理所当然该是如此啊。古人说得好：‘用割让土地去侍奉求饶强秦，好比抱着干柴去扑灭大火，干柴不烧尽，烈火就永远不会熄灭。’这句话真是说到了核心要害！",
