            "trans": "秦孝公去世之后，惠文王、武王、昭襄王相继继承先辈开创的基业，因循沿用商鞅留下的既定国策，向南攻取汉中要地，向西吞并巴、蜀全境，向东割取魏韩膏腴肥沃的平原良田，向北收取控制战略要害的边疆郡县。",
