            "trans": "关东东方各诸侯国陷入极度恐慌惊惧，召集会盟共同商讨削弱强秦的计策，不惜吝惜名贵器具无价重宝与肥沃辽阔的富饶土地，用来招揽延请天下的纵横谋士豪杰，缔结合纵抗秦盟约，结为亲密无间的一体联盟。",
