            "trans": "曾经凭借着数倍于秦国十倍的广大土地，纠集百万庞大之众的联军大军，猛烈叩击函谷关关门进攻秦国。秦军打开关门迎战迎击诱敌深入，九国庞大的联军军队，却犹豫徘徊迟疑顾虑吓得不敢前进。秦国没有耗费哪怕一矢一镝折断一支箭头的损耗代价，而天下的合纵诸侯却已经自相瓦解陷入精疲力竭的绝境了。于是合纵联盟破裂解体盟约失败，各诸侯国争先恐后割让土地去贿赂求饶秦国。",
