            "trans": "向南攻取平定百越全境的蛮荒土地，设立设置为桂林郡和象郡管辖；百越的部落首领君长，只能低头认罪用绳系颈屈辱投降，把身家性命完全交由秦国基层下级狱吏处置。始皇又派遣名将蒙恬向北修筑万里长城以此扼守帝国北部边防篱笆，击退迫使匈奴向北溃退七百多里。北方游牧胡人吓得多年不敢南下黄河沿岸放牧战马，六国残存的游侠武士也不敢拉开强弓向秦军寻仇报复复仇。",
