            "trans": "于是始皇废除古代圣明先王的德政王道，焚烧焚毁诸子百家的经典著述，以此推行愚民政策愚弄平民黔首；毁坏砸碎天下各地的坚固名城要塞，捕杀屠杀六国的英雄豪杰名门，收缴搜罗收缴全天下的所有铁器兵器刀枪，集中运送到国都咸阳，熔化销毁销铄锋利箭头兵刃，熔铸铸造成十二座巨大的青铜金人雕像，以此极度削弱削弱天下百姓的抗暴反抗力量。",
