            "trans": "然后登上险峻华山作为天然城墙，依凭浩荡黄河作为深邃护城河，倚仗高达亿丈高耸入云的天然坚城，俯临深不见底的险恶绝壁深渊，把这些当作万劫不破的坚固防线。智勇良将手持强劲战弩日夜驻守战略要害关隘，忠诚重臣率领精锐甲士手握锋利兵器厉声盘查谁敢造反。天下局面既然已经彻底平定，秦始皇狂妄骄横的心中，自以为关中根据地如此固若金汤，有绵延千里的钢铁长城庇佑，这必将是子子孙孙世世代代称帝称王、传承万世的千秋万古基业了。",
