            "trans": "当庄宗当年用绳索丝带将燕王刘守光父子捆绑生擒押解，用木匣木匣盛装着后梁君臣朱友贞的首级头颅，昂首阔步迈进太庙祖庙，将三支染血的利箭奉还归还给死去的先王，并且告慰大功告成的伟大胜利之时，他那时候意气风发气吞山河的鼎盛气概，真可以说是何等壮烈雄壮豪迈啊！",
