            "trans": "等到宿敌仇敌终于彻底消灭殆尽，天下四海局面大体平定安宁，伶人郭从谦等人在深夜振臂一呼，叛乱的乱兵四方云集蜂拥呼应，庄宗吓得仓皇失措带兵向东逃窜出京，还没来得及与叛贼正面交锋阵列前线，身边的精锐士卒兵勇就早已作鸟兽散四散溃散，君臣将士在绝境中面面相觑不知何去何从，甚至落魄绝望到削去长发用泥灰毁容割面伪装，君臣抱头痛哭眼泪打湿浸透了衣襟胸膛，这又是何等的凄惨衰败落魄啊！",
