            "trans": "难道真是夺取江山天下艰难困苦而丧失江山容易得很吗？还是推究考察他当年成功与后来失败的历史轨迹，而根本上全都是由人事自身的作为所一手造成的呢？《尚书》上说：‘骄傲自满招致亏损倾覆，谦逊谨慎得到益处福分。’艰难忧患辛勤操劳可以使国家繁荣兴盛，贪图安逸骄奢享乐足以使自身毁灭亡命，这本就是颠扑不破的大自然客观规律啊！",
