            "orig": "故方其盛也，举天下之豪杰，莫能与之争；及其衰也，数十伶人困之，而身死国灭，为天下笑。夫祸患常积于忽微，而智勇多困于所溺，岂独伶人也哉！作《伶官传》。",
            "trans": "所以当庄宗李存勖当年鼎盛势强之时，放眼全天下的当世英雄豪杰，没有一个人能够同他一争高下匹敌争锋；等到他晚年纵欲衰败堕落之时，仅仅区区几十个唱戏演戏的下贱伶人就把他围困逼上绝路，最终落得横死乱箭之下、身死国亡社稷沦丧的下场，沦为全天下后人万古笑柄耻笑的对象。大凡人世间的弥天大祸与致命祸患往往正是在微不足道疏忽的细微小节中日积月累造成的，而原本聪明智慧勇敢非凡的绝代雄豪往往正是在自己过分溺爱沉溺的嗜好事物中被彻底困死毁灭的，难道仅仅只是沉溺几个伶人演戏才会招致这样的恶果吗！特作此《伶官传》以为千秋鉴戒。",
