            "trans": "用吴地精蚕丝作弦、蜀地名桐木作琴身精雕细琢的箜篌在深秋爽朗的天空下弹奏，空旷荒山上方凝结的浮云沉醉颓废停滞不再飘流。湘江神女啼哭泪染斑竹素女心生无尽愁绪，正是乐坛大师李凭在国都长安城正中央纵情弹奏绝代箜篌。",
