            "trans": "我若真能写成这本巨著，把它珍藏在名山险阁，流传给懂得它的后代知己，播散到通衢大邑繁华都会，那我便偿清了先前蒙受奇耻大辱的重责，即使粉身碎骨被千刀万剐受诛杀戮万次，又怎会有丝毫怨悔呢！",
